/* All store-specific content lives in config.js and products.js. */
(() => {
 'use strict';
 const $ = (s,root=document)=>root.querySelector(s);
 const esc = v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const money = v=>new Intl.NumberFormat('ru-RU').format(v)+' ₽';
 const image = id=>'assets/images/'+id+'.jpg';
 const storageKey='flower-shop-cart-v1';
 const c=window.CATALOG, shop=window.SHOP;
 let cart=[], category=c.categories[0], toastTimer, lastFocus, modalView='', pending=false;
 const quantities=Object.fromEntries(c.flowers.map(f=>[f.id,0]));
 let pack=c.packaging[0].id, card=c.cards[0].id;
 function readCart(){try{const data=JSON.parse(localStorage.getItem(storageKey)||'[]');if(!Array.isArray(data))return;cart=data.slice(0,100).flatMap(row=>{if(!row||!Number.isInteger(row.qty)||row.qty<1||row.qty>99)return [];if(row.productId){const p=c.products.find(p=>p.id===row.productId);return p?[{...p,key:p.id,productId:p.id,qty:row.qty}]:[];}if(row.custom){const q={};for(const f of c.flowers)q[f.id]=Number.isInteger(row.custom.quantities?.[f.id])?Math.max(0,Math.min(99,row.custom.quantities[f.id])):0;const p=c.packaging.find(p=>p.id===row.custom.pack),a=c.cards.find(a=>a.id===row.custom.card);if(!p||!a||!Object.values(q).some(Boolean))return [];return [{...makeCustom(q,p.id,a.id),qty:row.qty}];}return [];});}catch{cart=[];}}
 function save(){try{localStorage.setItem(storageKey,JSON.stringify(cart.map(r=>r.productId?{productId:r.productId,qty:r.qty}:{custom:r.custom,qty:r.qty})));}catch{toast('Корзина доступна до закрытия страницы: сохранение браузера недоступно.');}updateCount();}
 function subtotal(){return cart.reduce((sum,p)=>sum+p.price*p.qty,0);}
 function delivery(method='delivery'){return method==='pickup'||subtotal()>=shop.delivery.freeFrom||!cart.length?0:shop.delivery.price;}
 function updateCount(){$('#cart-count').textContent=cart.reduce((s,p)=>s+p.qty,0);}
 function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3000);}
 function photo(p,attrs=''){return `<img src="${esc(image(p.image))}" alt="${esc(p.composition||p.name)}" ${attrs}>`;}
 function qtyControl(id,value,scope){return `<div class="qty"><button type="button" data-qty="${esc(id)}" data-delta="-1" data-scope="${scope}" aria-label="Уменьшить количество: ${esc(id)}" ${value<=0?'disabled':''}>−</button><output aria-label="Количество">${value}</output><button type="button" data-qty="${esc(id)}" data-delta="1" data-scope="${scope}" aria-label="Увеличить количество: ${esc(id)}" ${value>=99?'disabled':''}>+</button></div>`;}
 function open(title,body,view){if(!$('#modal').open)lastFocus=document.activeElement;$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;modalView=view;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;$('#close-modal').focus();}
 function close(){if(pending)return;$('#modal').close();}
 $('#close-modal').onclick=close;
 $('#modal').addEventListener('cancel',e=>{if(pending)e.preventDefault();});
 $('#modal').addEventListener('close',()=>{modalView='';lastFocus?.focus();});
 $('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close();}});
 function renderProducts(){let rows=c.products.filter(p=>category===c.categories[0]||p.category===category);const sort=$('#sort').value;if(sort!=='default')rows=[...rows].sort((a,b)=>sort==='asc'?a.price-b.price:b.price-a.price);$('#products').innerHTML=rows.map(p=>`<article class="product"><button class="product-image" data-detail="${p.id}" aria-label="Подробнее: ${esc(p.name)}">${photo(p,'loading="lazy" width="500" height="575"')}${p.tag?`<span class="tag">${esc(p.tag)}</span>`:''}</button><button class="product-name" data-detail="${p.id}">${esc(p.name)}</button><p class="composition">${esc(p.composition)}</p><div class="product-bottom"><strong class="price">${money(p.price)}</strong><button class="add-product" data-add="${p.id}" aria-label="В корзину: ${esc(p.name)}">В корзину <span aria-hidden="true">+</span></button></div></article>`).join('');}
 $('#filters').innerHTML=c.categories.map((cat,i)=>`<button type="button" data-category="${esc(cat)}" aria-pressed="${i===0}">${esc(cat)}</button>`).join('');
 $('#filters').onclick=e=>{const b=e.target.closest('[data-category]');if(!b)return;category=b.dataset.category;$('#filters').querySelectorAll('button').forEach(btn=>btn.setAttribute('aria-pressed',String(btn===b)));renderProducts();};
 $('#sort').onchange=renderProducts;
 function addProduct(id){const p=c.products.find(p=>p.id===id);const row=cart.find(r=>r.key===id);if(row){if(row.qty>=99)return toast('Максимум 99 букетов одной позиции.');row.qty++;}else cart.push({...p,key:p.id,productId:p.id,qty:1});save();toast('«'+p.name+'» - в корзине');}
 function detail(id){const p=c.products.find(p=>p.id===id);open(p.name,`${photo(p,'class="modal-image"')}<p>${esc(p.composition)}</p><p class="muted small">Точный состав и наличие уточняет флорист. Вазы и реквизит не включены.</p><div class="total"><span>Стоимость букета</span><strong>${money(p.price)}</strong></div><button class="button full" data-add="${p.id}">Добавить в корзину <span>+</span></button>`,'detail');}
 document.addEventListener('click',e=>{const add=e.target.closest('[data-add]');if(add)addProduct(add.dataset.add);const d=e.target.closest('[data-detail]');if(d)detail(d.dataset.detail);const q=e.target.closest('[data-qty]');if(q){const delta=Number(q.dataset.delta),id=q.dataset.qty;if(q.dataset.scope==='flower'){quantities[id]=Math.min(99,Math.max(0,quantities[id]+delta));updateFlowerQuantity(q.closest('.qty'),quantities[id]);renderBuilder();}else{const row=cart.find(r=>r.key===id);if(row){row.qty+=delta;if(row.qty<=0)cart=cart.filter(r=>r!==row);else row.qty=Math.min(99,row.qty);save();renderCart();const buttons=$('#modal-body').querySelectorAll('[data-qty]');[...buttons].find(b=>b.dataset.qty===id&&Number(b.dataset.delta)===delta)?.focus();}}}const remove=e.target.closest('[data-remove]');if(remove){cart=cart.filter(r=>r.key!==remove.dataset.remove);save();renderCart();}});
 function renderFlowers(){$('#flowers').innerHTML=c.flowers.map(f=>`<article class="flower">${photo(f,'loading="lazy" width="250" height="275"')}<h4>${esc(f.name)}</h4><p>${money(f.price)} / шт.</p>${qtyControl(f.id,quantities[f.id],'flower')}</article>`).join('');}
 function updateFlowerQuantity(control,value){
  $('output',control).textContent=value;
  $('[data-delta="-1"]',control).disabled=value<=0;
  $('[data-delta="1"]',control).disabled=value>=99;
 }
 function optionRows(rows){return rows.map(r=>`<option value="${r.id}">${esc(r.name)}${r.price?' · '+money(r.price):' · бесплатно'}</option>`).join('');}
 $('#packaging').innerHTML=optionRows(c.packaging);$('#greeting').innerHTML=optionRows(c.cards);
 $('#packaging').onchange=e=>{pack=e.target.value;renderBuilder();};$('#greeting').onchange=e=>{card=e.target.value;renderBuilder();};
 function makeCustom(q,packId,cardId){const selected=c.flowers.filter(f=>q[f.id]>0),p=c.packaging.find(p=>p.id===packId),a=c.cards.find(a=>a.id===cardId);const price=selected.reduce((s,f)=>s+f.price*q[f.id],0)+p.price+a.price;return {key:'custom-'+JSON.stringify([c.flowers.map(f=>q[f.id]||0),packId,cardId]),name:'Ваш особенный букет',price,composition:[...selected.map(f=>f.name+' × '+q[f.id]),p.name,a.name].join(', '),image:selected[0]?.image,custom:{quantities:{...q},pack:packId,card:cardId}};}
 function renderBuilder(){const selected=c.flowers.filter(f=>quantities[f.id]>0),p=c.packaging.find(p=>p.id===pack),a=c.cards.find(a=>a.id===card),custom=makeCustom(quantities,pack,card);$('#builder-lines').innerHTML=selected.length?`<ul>${selected.map(f=>`<li><span>${esc(f.name)} × ${quantities[f.id]}</span><span>${money(f.price*quantities[f.id])}</span></li>`).join('')}<li><span>${esc(p.name)}</span><span>${money(p.price)}</span></li>${a.price?`<li><span>${esc(a.name)}</span><span>${money(a.price)}</span></li>`:''}</ul>`:'<p class="muted small">Пока здесь чистый лист.<br>Добавьте цветы, которые нравятся.</p>';$('#builder-total').textContent=money(selected.length?custom.price:0);$('#add-custom').disabled=!selected.length;}
 $('#add-custom').onclick=()=>{if(!Object.values(quantities).some(Boolean))return;const custom=makeCustom(quantities,pack,card),existing=cart.find(r=>r.key===custom.key);if(existing){if(existing.qty>=99)return toast('Максимум 99 одинаковых букетов.');existing.qty++;}else cart.push({...custom,qty:1});save();toast('Ваш букет добавлен в корзину');};
 function renderCart(){if(!cart.length)return open('Ваша корзина','<div class="empty"><h3>Здесь пока нет цветов</h3><p>Выберите букет для себя или близкого человека.</p><button class="button" id="back-catalog">Перейти к букетам ↗</button></div>','cart');open('Ваша корзина',cart.map(r=>`<article class="cart-line">${photo(r)}<div><h3>${esc(r.name)}</h3><p>${esc(r.composition)}</p>${qtyControl(r.key,r.qty,'cart')}</div><div>${money(r.price*r.qty)}<button class="remove" data-remove="${esc(r.key)}" aria-label="Удалить ${esc(r.name)}">Удалить</button></div></article>`).join('')+`<div class="breakdown"><span>Букеты</span><span>${money(subtotal())}</span></div><div class="breakdown"><span>Доставка</span><span>${delivery()?money(delivery()):'Бесплатно'}</span></div><p class="small muted">${esc(shop.delivery.text)} При самовывозе доставка не начисляется.</p><div class="total"><span>С доставкой</span><strong>${money(subtotal()+delivery())}</strong></div><button class="button full" id="checkout">Перейти к оформлению ↗</button>`,'cart');}
 $('#open-cart').onclick=renderCart;
 document.addEventListener('click',e=>{if(e.target.closest('#checkout'))checkout();if(e.target.closest('#back-catalog')){close();location.hash='catalog';}if(e.target.closest('#back-cart'))renderCart();if(e.target.closest('#skip-feedback'))close();});
 function localDate(){const d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
 function checkout(){if(!cart.length)return renderCart();open('Оформление заказа',`<button class="remove" id="back-cart" style="margin:0 0 20px">Вернуться в корзину</button><form id="order-form"><div class="form-grid"><label class="field">Ваше имя<input name="name" autocomplete="given-name" required maxlength="80" placeholder="Как к вам обращаться"></label><label class="field">Телефон<input name="phone" type="tel" autocomplete="tel" required maxlength="30" placeholder="+7 (___) ___-__-__"></label></div><fieldset class="form-radio"><legend>Как получить букет</legend><label><input type="radio" name="method" value="delivery" checked> Доставка</label><label><input type="radio" name="method" value="pickup"> Самовывоз</label></fieldset><div class="form-grid" id="delivery-fields"><label class="field span2">Адрес доставки<input name="address" autocomplete="street-address" required maxlength="250" placeholder="Улица, дом, квартира"></label><label class="field">Желаемая дата<input name="date" type="date" required min="${localDate()}"></label><label class="field">Интервал<select name="interval">${shop.delivery.intervals.map(t=>`<option>${esc(t)}</option>`).join('')}</select></label></div><p id="pickup-info" class="small muted" hidden>${esc(shop.address)} · ${esc(shop.hours)}</p><label class="field" style="margin-top:17px">Комментарий - необязательно<textarea name="comment" maxlength="1000" placeholder="Например, текст для открытки"></textarea></label><div class="total"><span>Итого</span><strong id="checkout-total">${money(subtotal()+delivery())}</strong></div><p class="form-note">${shop.demo?'Отправка заказов пока не подключена. Для заказа свяжитесь с мастерской по телефону.':'Отправляя заказ, вы передаёте данные мастерской для его обработки.'}</p><p class="error" id="order-error" role="alert"></p><button class="button full" type="submit">${shop.demo?'Оформить заказ':'Отправить заказ'} ↗</button></form>`,'checkout');const form=$('#order-form');form.addEventListener('change',e=>{if(e.target.name==='method'){const pickup=form.elements.method.value==='pickup';$('#delivery-fields').hidden=pickup;$('#pickup-info').hidden=!pickup;$('#delivery-fields').querySelectorAll('input,select').forEach(el=>el.disabled=pickup);$('#checkout-total').textContent=money(subtotal()+delivery(form.elements.method.value));}});form.elements.phone.addEventListener('input',()=>form.elements.phone.setCustomValidity(''));form.elements.name.addEventListener('input',()=>form.elements.name.setCustomValidity(''));form.onsubmit=submitOrder;}
 async function submitOrder(e){e.preventDefault();if(pending)return;const form=e.currentTarget,values=Object.fromEntries(new FormData(form)),phoneDigits=values.phone.replace(/\D/g,'');if(!values.name.trim()){form.elements.name.setCustomValidity('Введите ваше имя.');form.reportValidity();return;}if(phoneDigits.length<10||phoneDigits.length>15){form.elements.phone.setCustomValidity('Введите телефон: от 10 до 15 цифр.');form.reportValidity();return;}if(values.method==='delivery'&&(!values.address?.trim()||values.date<localDate())){$('#order-error').textContent='Укажите адрес и дату не раньше сегодняшней.';return;}pending=true;const submit=form.querySelector('[type=submit]');submit.disabled=true;submit.textContent='Оформляем…';try{const result=await orderAdapter.submit({customer:values,items:cart.map(r=>({...r})),subtotal:subtotal(),delivery:delivery(values.method),total:subtotal()+delivery(values.method)});cart=[];save();pending=false;feedback(result);}catch(err){$('#order-error').textContent=err.message;submit.disabled=false;submit.textContent=shop.demo?'Оформить заказ':'Отправить заказ';}finally{pending=false;}}
 function feedback(result){open(result.demo?'Оформление завершено':'Заказ отправлен',`<p class="success-label">${esc(result.id)}</p><p class="muted small">${result.demo?'Заявка не отправлена. Чтобы подтвердить заказ, свяжитесь с мастерской по телефону.':'Спасибо! Мастерская уточнит детали заказа.'}</p><form id="feedback-form"><fieldset class="feedback-options"><legend>Было ли удобно оформить заказ?</legend>${['Да, всё понятно','Были небольшие сложности','Нужна помощь'].map((label,i)=>`<label><input type="radio" name="rating" value="${i}" required> ${label}</label>`).join('')}</fieldset><label class="field">Комментарий - необязательно<textarea name="comment" maxlength="1000"></textarea></label><p class="form-note">${shop.demo?'Отправка обратной связи пока не подключена.':'Ответ поможет улучшить оформление.'}</p><p id="feedback-error" class="error" role="alert"></p><div class="form-actions"><button type="submit" class="button">Отправить</button><button type="button" class="button secondary" id="skip-feedback">Пропустить</button></div></form>`,'feedback');$('#feedback-form').onsubmit=async e=>{e.preventDefault();if(pending)return;pending=true;const button=e.currentTarget.querySelector('[type=submit]');button.disabled=true;try{await orderAdapter.feedback({orderId:result.id,...Object.fromEntries(new FormData(e.currentTarget))});pending=false;open('Спасибо за обратную связь',`<p>${shop.demo?'Ответ не отправлен: подключение к мастерской пока недоступно.':'Ваш ответ отправлен.'}</p><button class="button" id="skip-feedback">Закрыть</button>`,'thanks');}catch(err){$('#feedback-error').textContent=err.message;button.disabled=false;}finally{pending=false;}};}
 document.querySelectorAll('[data-bind]').forEach(el=>el.textContent=shop[el.dataset.bind]||'');
 document.querySelectorAll('[data-phone]').forEach(el=>{el.textContent=shop.phone;el.href='tel:'+shop.phone.replace(/[^+\d]/g,'');});
 document.title=shop.title;document.querySelector('meta[name=description]').content=shop.description;
 $('#hero-title').textContent=shop.heroTitle;
 $('#delivery-text').textContent=shop.delivery.text;$('#delivery-timing').textContent=shop.delivery.timing;$('#year').textContent=new Date().getFullYear();
 $('#social-links').innerHTML=shop.links.filter(l=>/^https:\/\//.test(l.url)).map(l=>`<a href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">${esc(l.label)}</a>`).join(' · ');
 document.addEventListener('error',e=>{if(e.target.tagName==='IMG'){const img=e.target;if(img.dataset.failed)return;img.dataset.failed='true';img.removeAttribute('src');img.alt='Фотография временно недоступна';img.classList.add('image-missing');}},true);
 const authorLink=$('#author-link');
 try{const url=new URL(shop.authorUrl);if(url.protocol==='https:'&&url.hostname==='t.me')authorLink.href=url.href;}catch{}
 const reviews=window.SHOP_REVIEWS;
 if(reviews){
   let source;
   try{const url=new URL(reviews.sourceUrl);if(url.protocol==='https:'&&/^(?:[a-z0-9-]+\.)?2gis\.(ru|com|kz|kg|uz|by|am|az|ge|tj|ae)$/.test(url.hostname))source=url.href;}catch{}
   if(source){
     $('#reviews-source').href=source;
     $('#review-business').textContent=reviews.businessName;
     $('#review-address').textContent=reviews.address;
     $('#reviews-note').textContent=reviews.note;
     $('#review-cards').innerHTML=reviews.items.map(r=>`<article class="review"><div class="review-top"><span class="review-avatar" aria-hidden="true">${esc(r.author.slice(0,1))}</span><h3>${esc(r.author)}</h3><span class="review-platform">2ГИС</span></div><blockquote>${esc(r.text)}</blockquote><a class="review-original" href="${esc(source)}" target="_blank" rel="noopener noreferrer">Читать в 2ГИС <span aria-hidden="true">↗</span></a></article>`).join('');
   }else $('#reviews').hidden=true;
 }else $('#reviews').hidden=true;
 readCart();updateCount();renderProducts();renderFlowers();renderBuilder();
 window.addEventListener('storage',e=>{if(e.key===storageKey){readCart();updateCount();if(modalView==='cart')renderCart();if(modalView==='checkout'){if(cart.length)checkout();else renderCart();}}});
})();
